css:
.row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.btn {
  --btn-bg: #f97316;
  --btn-fg: #ffffff;
  --btn-line: #f97316;
  --btn-pad: 10px 18px;
  --btn-size: 16px;
  --btn-radius: 8px;

  padding: var(--btn-pad);
  border: 2px solid var(--btn-line);
  border-radius: var(--btn-radius);
  background-color: var(--btn-bg);
  color: var(--btn-fg);
  font: inherit;
  font-size: var(--btn-size);
  cursor: pointer;
}

.small {
  --btn-pad: 4px 10px;
  --btn-size: 13px;
}

.danger {
  --btn-bg: #dc2626;
  --btn-line: #dc2626;
}

.ghost {
  --btn-bg: transparent;
  --btn-fg: #c2410c;
}
